<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientResponseTypesJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientResponseTypesJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withResponseTypesJson,
 * getResponseTypesJson/responseTypesJson accessors, and isResponseTypesJsonChanged with/without original.
 */
class TrustedClientResponseTypesJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withResponseTypesJson creates a new instance with the ResponseTypesJson set
     * from a string value, and getResponseTypesJson returns the primitive string.
     */
    public function testWithResponseTypesJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientResponseTypesJsonAccessorUnitTest();

        // Act
        $result = $holder->withResponseTypesJson([]);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals([], $result->getResponseTypesJson());
    }
    /**
     * Asserts that withresponseTypesJson has access to the value object
     * from a string value, and getResponseTypesJson returns the primitive string.
     */
    public function testWithResponseTypesJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientResponseTypesJsonAccessorUnitTest();

        // Act
        $result = $holder->withResponseTypesJson([]);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals([], $result->responseTypesJson()->value());
    }
    public function testChangedResponseTypesJson(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientResponseTypesJsonAccessorUnitTest();
        $original = $holder->withResponseTypesJson([]);
        $same = $holder->withResponseTypesJson([]);
        $modified = $holder->withResponseTypesJson([]);

        // Act
        $unchanged = $holder->isResponseTypesJsonChanged();
        $withSame = $original->isResponseTypesJsonChanged($same);
        $withDiferent = $original->isResponseTypesJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientResponseTypesJsonAccessorUnitTest
{
    use TrustedClientResponseTypesJsonAccessor;
}
